head.script:
//
window.addEventListener('load', function() {
  // 1. ЦЕНТРУВАННЯ ЗАГОЛОВКА
  var blogName = document.querySelector('.blog-name');
  if (blogName) {
    blogName.style.setProperty('margin', '0 auto', 'important');
    blogName.style.setProperty('display', 'table', 'important');
    blogName.style.setProperty('text-align', 'center', 'important');
    blogName.style.setProperty('position', 'relative', 'important');
    blogName.style.setProperty('z-index', '1', 'important');
  }

  // 2. АДАПТИВНІСТЬ КАРТОК (Тільки для мобільних)
  if (window.innerWidth < 900) {
    var posts = document.querySelectorAll('.post-outer-container, article.post, .post-outer, .post');
    for (var i = 0; i < posts.length; i++) {
      posts[i].style.setProperty('width', '100%', 'important');
      posts[i].style.setProperty('max-width', '100%', 'important');
      posts[i].style.setProperty('position', 'relative', 'important');
      posts[i].style.setProperty('left', '0', 'important');
      posts[i].style.setProperty('top', 'auto', 'important');
      posts[i].style.setProperty('transform', 'none', 'important');
      posts[i].style.setProperty('display', 'block', 'important');
      posts[i].style.setProperty('margin-bottom', '45px', 'important');
    }
  }

  // 3. ПРИМУСОВЕ ВІДКРИТТЯ МЕНЮ (Безвідмовний обхід бага Blogger)
  var menuContainers = document.querySelectorAll('.hamburger-menu-container, .hamburger-menu');
  var sidebar = document.querySelector('.sidebar-container');
  var body = document.body;

  if (sidebar && menuContainers.length > 0) {
    // Піднімаємо сайдбар на самий верх, щоб ніщо його не перекрило
    sidebar.style.setProperty('z-index', '100000', 'important');

    menuContainers.forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        e.stopPropagation(); // Блокуємо завислий скрипт Blogger

        // Ручне перемикання класів для виїзду меню
        if (body.classList.contains('sidebar-visible')) {
           body.classList.remove('sidebar-visible');
           sidebar.classList.add('sidebar-invisible');
        } else {
           body.classList.add('sidebar-visible');
           sidebar.classList.remove('sidebar-invisible');
        }
      });
    });
  }

  // 4. ПРИМУСОВЕ ЗАКРИТТЯ МЕНЮ (при кліку на затемнений фон або кнопку "Назад")
  var dimOverlay = document.querySelector('.dim-overlay');
  var sidebarBack = document.querySelector('.sidebar-back');

  if (dimOverlay) {
    dimOverlay.addEventListener('click', function() {
       body.classList.remove('sidebar-visible');
       sidebar.classList.add('sidebar-invisible');
    });
  }

  if (sidebarBack) {
    sidebarBack.addEventListener('click', function() {
       body.classList.remove('sidebar-visible');
       sidebar.classList.add('sidebar-invisible');
    });
  }
});
//

//
window.addEventListener('load', function() {
  // 1. ЦЕНТРУВАННЯ ЗАГОЛОВКА (БЕЗ БЛОКУВАННЯ МЕНЮ)
  var blogName = document.querySelector('.blog-name');
  if (blogName) {
    // Ми не робимо width: 100%, щоб залишити місце для кнопок
    blogName.style.setProperty('margin', '0 auto', 'important');
    blogName.style.setProperty('display', 'table', 'important'); /* Це ключовий момент для центрування */
    blogName.style.setProperty('text-align', 'center', 'important');
    blogName.style.setProperty('position', 'relative', 'important');
    blogName.style.setProperty('z-index', '1', 'important');
  }

  // 2. АДАПТИВНІСТЬ КАРТОК (Тільки для мобільних)
  if (window.innerWidth < 900) {
    var posts = document.querySelectorAll('.post-outer-container, article.post, .post-outer, .post');
    for (var i = 0; i < posts.length; i++) {
      posts[i].style.setProperty('width', '100%', 'important');
      posts[i].style.setProperty('max-width', '100%', 'important');
      posts[i].style.setProperty('position', 'relative', 'important');
      posts[i].style.setProperty('left', '0', 'important');
      posts[i].style.setProperty('top', 'auto', 'important');
      posts[i].style.setProperty('transform', 'none', 'important');
      posts[i].style.setProperty('display', 'block', 'important');
      posts[i].style.setProperty('margin-bottom', '45px', 'important');
    }
  }
});
